package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ListPopulation#iterator.
 */
public class ListPopulation_iterator_TriageGen0Test {

    /**
     * Mock Chromosome implementation for testing purposes.
     */
    private static class MockChromosome implements Chromosome {
        private final int id;

        MockChromosome(int id) {
            this.id = id;
        }

        @Override
        public double getFitness() {
            return id;
        }

        @Override
        public Chromosome copy() {
            return new MockChromosome(id);
        }

        @Override
        public String toString() {
            return "MockChromosome{" + id + "}";
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Chromosome)) return false;
            return id == ((MockChromosome) obj).id;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(id);
        }
    }

    @Test
    public void testIteratorEmptyPopulation() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertFalse("Iterator should be empty for an empty population", iterator.hasNext());
    }

    @Test
    public void testIteratorWithMultipleChromosomes() {
        int limit = 10;
        Chromosome c1 = new MockChromosome(1);
        Chromosome c2 = new MockChromosome(2);
        Chromosome c3 = new MockChromosome(3);
        List<Chromosome> chromosomes = Arrays.asList(c1, c2, c3);

        ListPopulation population = new ListPopulation(chromosomes, limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertTrue("Iterator should have elements", iterator.hasNext());

        // Verify all elements are returned in order
        int count = 0;
        while (iterator.hasNext()) {
            Chromosome current = iterator.next();
            assertEquals("Chromosome mismatch at index " + count, chromosomes.get(count), current);
            count++;
        }

        assertEquals("Iterator should have returned exactly 3 elements", 3, count);
        assertFalse("Iterator should be exhausted", iterator.hasNext());
    }

    @Test
    public void testIteratorAfterAddingChromosomes() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);

        Chromosome c1 = new MockChromosome(1);
        Chromosome c2 = new MockChromosome(2);

        population.addChromosome(c1);
        population.addChromosome(c2);

        Iterator<Chromosome> iterator = population.iterator();

        assertTrue(iterator.hasNext());
        assertEquals(c1, iterator.next());
        assertTrue(iterator.hasNext());
        assertEquals(c2, iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIteratorAfterSetChromosomes() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);

        Chromosome c1 = new MockChromosome(1);
        List<Chromosome> newList = new ArrayList<>();
        newList.add(c1);

        population.setChromosomes(newList);

        Iterator<Chromosome> iterator = population.iterator();

        assertTrue(iterator.hasNext());
        assertEquals(c1, iterator.next());
        assertFalse(iterator.hasNext());
    }
}
